"use strict";

// ---------------------------------------------------------------- helpers

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

async function api(path, { method = "GET", body, form, signal } = {}) {
  const opts = { method, headers: {}, signal };
  if (form) opts.body = form;
  else if (body !== undefined) {
    opts.headers["content-type"] = "application/json";
    opts.body = JSON.stringify(body);
  }
  const res = await fetch(path, opts);
  let data = null;
  try { data = await res.json(); } catch { /* empty body */ }
  if (!res.ok) throw new Error(data?.detail || `HTTP ${res.status}`);
  return data;
}

// Name shown in the sidebar and tab titles; /api/meta can override it (local branding).
const brand = { name: "Papple Music", tagline: "Enhanced Downloader", wordmark: false };

const store = {
  get(key, fallback) {
    try { return JSON.parse(localStorage.getItem(`gamdl-web:${key}`)) ?? fallback; } catch { return fallback; }
  },
  set(key, value) {
    try { localStorage.setItem(`gamdl-web:${key}`, JSON.stringify(value)); } catch { /* storage unavailable */ }
  },
};

const fmtTime = (ts) => new Date(ts * 1000).toLocaleTimeString(i18n.locale, { hour12: false });
const fmtDate = (ts) => new Date(ts * 1000).toLocaleString(i18n.locale, { dateStyle: "medium", timeStyle: "short" });

function fmtDuration(seconds) {
  seconds = Math.max(0, Math.round(seconds));
  const m = Math.floor(seconds / 60), s = seconds % 60;
  return m ? `${m}분 ${s}초` : `${s}초`;
}

