const picon = (name) => {
  const p = PICONS[name];
  return `<svg class="picon" viewBox="0 0 ${p.vb[0]} ${p.vb[1]}" style="--w:${p.size[0]}px;--h:${p.size[1]}px" aria-hidden="true">${p.g}</svg>`;
};

const icon = (name) =>
  `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]}</svg>`;

function hydrateIcons(root = document) {
  $$("[data-icon]", root).forEach((el) => { el.innerHTML = icon(el.dataset.icon); });
}

function toast(message, kind = "info") {
  const el = document.createElement("div");
  el.className = `toast ${kind}`;
  el.innerHTML = `<span class="status-icon">${icon({ ok: "check", err: "alert" }[kind] || "info")}</span><span></span>`;
  el.lastChild.textContent = message;
  $("#toasts").append(el);
  setTimeout(() => {
    el.classList.add("leaving");
    setTimeout(() => el.remove(), 300);
  }, kind === "err" ? 6500 : 3200);
}

// ---------------------------------------------------------------- state

